export type TenantType = 'family' | 'clinic';
export type CaregiverRole = 'caregiver' | 'clinic_coordinator';
export type CommandUrgency = 'emergency' | 'routine';
export type CommandSensitivity = 'low' | 'medium' | 'high';
export type EventFeedback = 'not_evaluated' | 'real' | 'false_positive';
export type EdgeDeviceStatus = 'online' | 'offline';

/** Care unit — family or clinic (multi-tenant, schema-per-tenant) */
export interface Tenant {
  id: string;  // string
  name: string;  // string
  type: TenantType;  // enum
}

/** Person monitored by the system */
export interface Patient {
  id: string;  // string
  tenantId: string;  // ref → Tenant
  name: string;  // string
  device: string;  // ref → EdgeDevice
}

/** Person with access to the dashboard */
export interface Caregiver {
  id: string;  // string
  tenantId: string;  // ref → Tenant
  name: string;  // string
  email: string;  // string
  role: CaregiverRole;  // enum
}

/** Extensible catalog of facial movement types (primitives) — Amendment 2, 2026-07-27.
 * The user can register new types (e.g. "Lip reading") directly on Screen 04.
 * Registering the name here does NOT imply real detection-engine support — see
 * TODO[architect] in Framing §6.1/§9.3. */
export interface GestureType {
  id: string;  // string
  name: string;  // string
}

/** Item of the patient's command catalog — gesture (simple or compound) mapped to a need (LBC Amendment 1, 2026-07-27) */
export interface Command {
  id: string;  // string
  patientId: string;  // ref → Patient
  label: string;  // string
  urgency: CommandUrgency;  // enum
  primaryPrimitive: string;  // ref → GestureType
  secondaryPrimitive: string | null;  // ref → GestureType
  sensitivity: CommandSensitivity;  // enum
  minGestureDurationMs: number;  // int
  maxGestureDurationMs: number;  // int
}

/** Structured occurrence generated by the edge */
export interface Event {
  id: string;  // string
  patientId: string;  // ref → Patient
  command: string;  // ref → Command
  timestamp: string;  // datetime
  confirmedAt: string | null;  // datetime
  confirmedBy: string;  // ref → Caregiver
  feedback: EventFeedback;  // enum
}

/** Local agent that runs gesture detection */
export interface EdgeDevice {
  id: string;  // string
  patientId: string;  // ref → Patient
  status: EdgeDeviceStatus;  // enum
  lastSyncAt: string;  // datetime
  version: string;  // string
}

// =============================================================================
// Amendment 3 (2026-08-30) — CONV module. ADR-012/013 (accepted). Added by hand
// in this amendment; the next regeneration via `python main.py <project> --force`
// should reproduce these types from design/data-model.json (already updated).
// =============================================================================

export type SpeechTreeNodeType = 'category' | 'phrase';
export type PatientSessionStatus = 'active' | 'revoked';

// =============================================================================
// Amendment 4 (2026-08-31) — Elasticsearch/pure retrieval (ADR-015), collaborative LLM
// TRAINING phase (ADR-016), cached ElevenLabs TTS (ADR-017), English-only product
// (ADR-018; the former EN/PT bilingual decision was dropped). Added by hand in this amendment.
// NIV note: English-only product; pt-BR locale removed (see ADR-018-english-only-product).
// =============================================================================

export type Locale = 'en';

/** Content of a SpeechTreeNode in the (English) locale — text + cached audio +
 * Dual Authorization (ADR-016/ADR-018). Only when caregiverConfirmed AND patientConfirmed
 * are both true, the content is indexed (Elasticsearch) and synthesized (ElevenLabs). */
export interface ContentLocale {
  text: string;  // string
  audioRef: string | null;  // reference to the cached audio (not the binary) — null if not yet synthesized
  caregiverConfirmed: boolean;  // RBAC: training.node.approve.caregiver
  patientConfirmed: boolean;  // RBAC: training.node.approve.patient
}

/** Speech-tree node — category or phrase (ADR-013). null parentId = root.
 * content is keyed by Locale (Amendment 4, ADR-018) — text/audio are no longer a single field. */
export interface SpeechTreeNode {
  id: string;  // string
  patientId: string;  // ref → Patient
  parentId: string | null;  // ref → SpeechTreeNode
  type: SpeechTreeNodeType;  // enum
  content: Record<Locale, ContentLocale>;  // Amendment 4 — used to be `text: string`
  order: number;  // int
  engineFeatureRef: string | null;  // unified gesture vocabulary (commit 89f4ee5 of the real repo)
  proposedByTraining: boolean;  // Amendment 4 — true if originated from the LLM in the TRAINING phase (ADR-016), false if seed predating Amendment 4
}

/** Patient's persistent app session, provisioned by the caregiver (ADR-012, Option C). */
export interface PatientSession {
  id: string;  // string
  patientId: string;  // ref → Patient
  provisionedBy: string;  // ref → Caregiver
  deviceId: string;  // ref → EdgeDevice
  status: PatientSessionStatus;  // enum
  provisionedAt: string;  // datetime
  revokedAt: string | null;  // datetime
  revokedBy: string | null;  // ref → Caregiver
}
